const item = $input.first();
const binary = item.binary?.screenshot;
if (!binary) throw new Error('Missing binary field: screenshot');
const allowed = ['image/png', 'image/jpeg', 'image/webp'];
if (!allowed.includes(binary.mimeType)) throw new Error('Only PNG, JPEG, and WebP screenshots are supported');
if (!binary.data) throw new Error('Screenshot binary has no data');
return [{ json: { context: item.json?.context || '', mimeType: binary.mimeType, fileName: binary.fileName || 'screenshot' }, binary: item.binary }];

const input = $input.first().json;
const source = typeof input.response === 'string' ? input.response : input.response?.response;
if (!source) throw new Error('Ollama returned no response field');
let report;
try { report = JSON.parse(source); } catch (error) { throw new Error('Ollama response is not valid JSON: ' + error.message); }
const required = ['title','summary','steps_to_reproduce','expected_result','actual_result','environment','severity','priority','labels','confidence','assumptions'];
const missing = required.filter((field) => !(field in report));
if (missing.length) throw new Error('Ollama report is missing: ' + missing.join(', '));
if (!Array.isArray(report.steps_to_reproduce) || !Array.isArray(report.labels) || !Array.isArray(report.assumptions)) throw new Error('Ollama report arrays are invalid');
if (typeof report.confidence !== 'number' || report.confidence < 0 || report.confidence > 1) throw new Error('Ollama confidence must be a number between 0 and 1');
const sourceItem = $('Validate Screenshot').first();
return [{ json: { report, mimeType: sourceItem.json.mimeType, fileName: sourceItem.json.fileName }, binary: sourceItem.binary }];

const item = $input.first();
const configuredIssueUrl = $env.JIRA_ISSUE_URL || $env.JIRA_URL || 'https://rahul-mansing-jamadar.atlassian.net/rest/api/3/issue';
const issueUrl = configuredIssueUrl.replace(/\/$/, '');
const baseUrl = issueUrl.replace(/\/rest\/api\/3\/issue$/, '');
const projectKey = $env.JIRA_PROJECT_KEY || 'VWO';
const issueType = $env.JIRA_ISSUE_TYPE || 'Bug';
const missing = [];
if (!baseUrl || baseUrl === issueUrl) missing.push('JIRA_ISSUE_URL or JIRA_URL must end with /rest/api/3/issue');
if (!item.json.report) throw new Error('Bug report is missing before Jira creation');
return [{ json: { ...item.json, jiraIssueUrl: issueUrl, jiraBaseUrl: baseUrl, jiraProjectKey: projectKey, jiraIssueType: issueType }, binary: item.binary }];

const issue = $input.first().json;
const source = $('Validate Bug Report').first();
if (!issue.key) throw new Error('Jira did not return an issue key');
if (!source.binary?.screenshot) throw new Error('Screenshot binary was lost before Jira attachment');
return [{ json: { issueKey: issue.key, report: source.json.report, mimeType: source.json.mimeType, fileName: source.json.fileName }, binary: source.binary }];
